import os
from google.cloud import documentai

def extract_layout(payload, config=None):
    config = config or {}

    # Initialize Document AI client
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    location = os.environ.get("GOOGLE_CLOUD_LOCATION", "us") # e.g., "us"
    processor_id = os.environ.get("GOOGLE_CLOUD_PROCESSOR_ID") # e.g., "YOUR_PROCESSOR_ID_HERE"

    if not all([project_id, location, processor_id]):
        raise ValueError("Missing GOOGLE_CLOUD_PROJECT_ID, GOOGLE_CLOUD_LOCATION, or GOOGLE_CLOUD_PROCESSOR_ID environment variables.")

    processor_name = f"projects/{project_id}/locations/{location}/processors/{processor_id}"

    client = documentai.DocumentProcessorServiceClient()

    # Prepare document
    document_content = payload['content'] # Assuming payload['content'] is bytes
    mime_type = payload.get('mime_type', 'application/pdf') # Default to PDF

    raw_document = documentai.RawDocument(content=document_content, mime_type=mime_type)

    # Configure the process request
    request = documentai.ProcessRequest(
        name=processor_name,
        raw_document=raw_document,
        # Set `skip_human_review` to True to disable human review (default is False).
        # For layout extraction, a specific processor like "Form Parser" (ID: FORM_PARSER_PROCESSOR_ID)
        # or "General Processor" (ID: OCR_PROCESSOR_ID) would be used.
        # This example assumes a processor capable of basic layout extraction.
    )

    # Process the document
    response = client.process_document(request=request)

    # Extract relevant layout information
    document = response.document

    # Basic layout extraction: text, pages, and their blocks/lines
    extracted_data = {
        "text": document.text,
        "pages": []
    }

    for page in document.pages:
        page_info = {
            "page_number": page.page_number,
            "dimension": {"width": page.dimension.width, "height": page.dimension.height, "unit": page.dimension.unit},
            "blocks": [],
            "lines": [],
            "tokens": [],
            "tables": [],
            "form_fields": []
        }

        # Example of extracting tokens (words)
        for token in page.tokens:
            page_info["tokens"].append({
                "text": documentai.get_text_anchor_text(token.layout.text_anchor, document.text),
                "bounding_box": [{"x": v.x, "y": v.y} for v in token.layout.bounding_poly.vertices]
            })

        # Example of extracting lines
        for line in page.lines:
            page_info["lines"].append({
                "text": documentai.get_text_anchor_text(line.layout.text_anchor, document.text),
                "bounding_box": [{"x": v.x, "y": v.y} for v in line.layout.bounding_poly.vertices]
            })

        # Example of extracting tables
        for table in page.tables:
            table_data = {
                "header_rows": [],
                "body_rows": []
            }
            for header_row in table.header_rows:
                row_cells = []
                for cell in header_row.cells:
                    row_cells.append(documentai.get_text_anchor_text(cell.layout.text_anchor, document.text))
                table_data["header_rows"].append(row_cells)

            for body_row in table.body_rows:
                row_cells = []
                for cell in body_row.cells:
                    row_cells.append(documentai.get_text_anchor_text(cell.layout.text_anchor, document.text))
                table_data["body_rows"].append(row_cells)
            page_info["tables"].append(table_data)

        # Example of extracting form fields (key-value pairs)
        for form_field in page.form_fields:
            page_info["form_fields"].append({
                "field_name": documentai.get_text_anchor_text(form_field.field_name.text_anchor, document.text),
                "field_value": documentai.get_text_anchor_text(form_field.field_value.text_anchor, document.text)
            })

        extracted_data["pages"].append(page_info)
    result = extracted_data
    return result
